func New(spec Spec, now time.Time) (Record, error) {
	if now.IsZero() || spec.StartedAt.After(now) {
		return Record{}, fmt.Errorf("%w: start time", ErrInvalid)
	}
	if slices.Contains(spec.KnownBad, spec.ToDigest) {
		return Record{}, ErrKnownBad
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return Record{}, err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return Record{}, err
	}
	units := make(map[string]UnitProgress, len(spec.Units))
	for _, unit := range spec.Units {
		units[unit.ID] = UnitProgress{State: UnitPending, Group: unit.Group, Seed: unit.Seed}
	}
	for wave, ids := range waves {
		for _, id := range ids {
			progress := units[id]
			progress.Wave = wave
			units[id] = progress
		}
	}
	knownBad := slices.Clone(spec.KnownBad)
	slices.Sort(knownBad)
	started := spec.StartedAt
	if started.IsZero() {
		started = now
	}
	record := Record{
		SchemaVersion: SchemaVersion, RolloutID: spec.RolloutID, Kind: spec.Kind, Cell: spec.Cell,
		FromDigest: spec.FromDigest, ToDigest: spec.ToDigest, Policy: spec.Policy, PolicyDigest: policyDigest,
		Phase: PhasePending, Waves: waves, Units: units, KnownBad: slices.Compact(knownBad),
		StartedAt: started.UTC(), PhaseStartedAt: now.UTC(), AuthorityEpoch: spec.AuthorityEpoch,
	}
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	return record, nil
}

const (
	SchemaVersion = 1
	// MaxUnits bounds one rollout record so it stays well under the KV value
	// limit while covering every controller and managed host in a cell.
	MaxUnits = 512
	// MaxKnownBad bounds the cell's durable known-bad digest list.
	MaxKnownBad = 256
	maxReason   = 512
)

var (
	ErrInvalid           = errors.New("rollout input is invalid")
	ErrInvalidTransition = errors.New("rollout event is not valid in the current phase")
	ErrTerminal          = errors.New("rollout is in a terminal phase")
	ErrKnownBad          = errors.New("rollout target digest is known bad")
	ErrAttemptsExhausted = errors.New("rollout target digest has no attempts left")
	ErrActiveRollout     = errors.New("another rollout is active in this cell")
	ErrFenced            = errors.New("rollout record belongs to a different authority epoch")
	ErrConflict          = errors.New("rollout record changed concurrently")

	tokenRE  = regexp.MustCompile(`^[a-z0-9][a-z0-9_.-]{0,127}$`)
	nonceRE  = regexp.MustCompile(`^[0-9a-f]{32}$`)
	digestRE = regexp.MustCompile(`^[0-9a-f]{64}$`)
)

