func DefaultPolicy() Policy {
	return Policy{
		CanaryUnits: 1, BatchSize: MaxUnits,
		CanarySoakSeconds: int64((5 * time.Minute).Seconds()), BatchSoakSeconds: int64((2 * time.Minute).Seconds()),
		MinHealthyReports: 3, ProofDeadlineSeconds: int64((10 * time.Minute).Seconds()),
		RollbackDeadlineSeconds: int64((10 * time.Minute).Seconds()), PreflightSeconds: int64((10 * time.Minute).Seconds()),
		MaxAttempts: 1, MaxRollbackRetries: 3,
	}
}

// Validate rejects policies that could skip the canary, soak or deadlines.
func (policy Policy) Validate() error {
	if policy.CanaryUnits < 1 || policy.CanaryUnits > MaxUnits || policy.BatchSize < 1 || policy.BatchSize > MaxUnits ||
		policy.CanarySoakSeconds < 0 || policy.BatchSoakSeconds < 0 || policy.MinHealthyReports < 1 ||
		policy.ProofDeadlineSeconds < 1 || policy.RollbackDeadlineSeconds < 1 || policy.PreflightSeconds < 1 ||
		policy.MaxAttempts < 1 || policy.MaxRollbackRetries < 0 {
		return fmt.Errorf("%w: policy bounds", ErrInvalid)
	}
	return nil
}

// Digest is SHA-256 of the canonical policy encoding.
func (policy Policy) Digest() (string, error) {
	encoded, err := protocol.EncodeJSON(policy)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(encoded)
	return hex.EncodeToString(sum[:]), nil
}

func seconds(value int64) time.Duration { return time.Duration(value) * time.Second }

func (record Record) Validate() error {
	if record.SchemaVersion != SchemaVersion || !entityid.Valid(record.RolloutID) || !record.Kind.valid() ||
		!tokenRE.MatchString(record.Cell) || !digestRE.MatchString(record.FromDigest) || !digestRE.MatchString(record.ToDigest) ||
		record.FromDigest == record.ToDigest || record.AuthorityEpoch == 0 || record.StartedAt.IsZero() ||
		record.PhaseStartedAt.IsZero() || len(record.Reason) > maxReason || len(record.KnownBad) > MaxKnownBad {
		return fmt.Errorf("%w: record identity", ErrInvalid)
	}
	if err := record.Policy.Validate(); err != nil {
		return err
	}
	if digest, err := record.Policy.Digest(); err != nil || digest != record.PolicyDigest {
		return fmt.Errorf("%w: policy digest", ErrInvalid)
	}
	switch record.Phase {
	case PhasePending, PhasePreflight, PhaseCanary, PhaseCanarySoak, PhaseBatch, PhaseBatchSoak,
		PhaseComplete, PhaseRollingBack, PhaseFrozen, PhaseAborted, PhaseRolledBack:
	default:
		return fmt.Errorf("%w: phase", ErrInvalid)
	}
	if len(record.Waves) == 0 || len(record.Units) == 0 || len(record.Units) > MaxUnits ||
		record.WaveIndex < 0 || record.WaveIndex >= len(record.Waves) {
		return fmt.Errorf("%w: waves", ErrInvalid)
	}
	seen := make(map[string]struct{}, len(record.Units))
	for wave, ids := range record.Waves {
		if len(ids) == 0 {
			return fmt.Errorf("%w: empty wave", ErrInvalid)
		}
		for _, id := range ids {
			progress, exists := record.Units[id]
			if _, duplicate := seen[id]; duplicate || !exists || progress.Wave != wave || !tokenRE.MatchString(progress.Group) {
				return fmt.Errorf("%w: wave unit %q", ErrInvalid, id)
			}
			seen[id] = struct{}{}
		}
	}
	if len(seen) != len(record.Units) {
		return fmt.Errorf("%w: unit outside every wave", ErrInvalid)
	}
	for _, id := range record.RollbackOrder {
		if _, exists := record.Units[id]; !exists {
			return fmt.Errorf("%w: rollback unit %q", ErrInvalid, id)
		}
	}
	for _, digest := range record.KnownBad {
		if !digestRE.MatchString(digest) {
			return fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
	}
	if slices.Contains(record.KnownBad, record.FromDigest) {
		return fmt.Errorf("%w: rollback target is known bad", ErrInvalid)
	}
	return record.validatePhaseUnits()
}

// validatePhaseUnits rejects phase and unit-state contradictions that Apply
// never produces, so a record built outside Apply is refused at the storage
// boundary instead of driving effects.
func (record Record) validatePhaseUnits() error {
	for _, id := range record.Waves[record.WaveIndex] {
		state := record.Units[id].State
		if record.Phase.soaking() && state != UnitSoaking ||
			record.Phase.preparing() && state != UnitPreparing && state != UnitSoaking {
			return fmt.Errorf("%w: phase %s contradicts unit %q in state %s", ErrInvalid, record.Phase, id, state)
		}
	}
	if record.Phase == PhaseRollingBack && record.rollbackHead() == "" {
		return fmt.Errorf("%w: rolling back without a unit to roll back", ErrInvalid)
	}
	return nil
}

func (record Record) abortedBeforeUpdate() bool {
	if record.Phase != PhaseAborted || len(record.RollbackOrder) != 0 {
		return false
	}
	for _, progress := range record.Units {
		if progress.State != UnitPending {
			return false
		}
	}
	return true
}

func PlanWaves(units []Unit, policy Policy) ([][]string, error) {
	if err := policy.Validate(); err != nil {
		return nil, err
	}
	if len(units) == 0 || len(units) > MaxUnits {
		return nil, fmt.Errorf("%w: unit count", ErrInvalid)
	}
	ordered := slices.Clone(units)
	slices.SortFunc(ordered, func(a, b Unit) int { return cmp.Compare(a.ID, b.ID) })
	var seeds, rest []Unit
	seen := make(map[string]struct{}, len(ordered))
	for _, unit := range ordered {
		if !tokenRE.MatchString(unit.ID) || !tokenRE.MatchString(unit.Group) {
			return nil, fmt.Errorf("%w: unit identity %q", ErrInvalid, unit.ID)
		}
		if _, duplicate := seen[unit.ID]; duplicate {
			return nil, fmt.Errorf("%w: duplicate unit %q", ErrInvalid, unit.ID)
		}
		seen[unit.ID] = struct{}{}
		if unit.Seed {
			seeds = append(seeds, unit)
		} else {
			rest = append(rest, unit)
		}
	}
	if len(seeds) > 1 {
		return nil, fmt.Errorf("%w: more than one seed unit", ErrInvalid)
	}
	var waves [][]string
	first := true
	for len(rest) > 0 {
		limit := policy.BatchSize
		if first {
			limit = policy.CanaryUnits
		}
		wave, remaining := takeWave(rest, limit)
		waves = append(waves, wave)
		rest = remaining
		first = false
	}
	for _, seed := range seeds {
		waves = append(waves, []string{seed.ID})
	}
	return waves, nil
}

// takeWave greedily selects up to limit units with pairwise distinct groups,
// preserving order for the units it leaves behind.
func takeWave(units []Unit, limit int) ([]string, []Unit) {
	groups := map[string]struct{}{}
	var wave []string
	var remaining []Unit
	for _, unit := range units {
		if _, taken := groups[unit.Group]; len(wave) < limit && !taken {
			groups[unit.Group] = struct{}{}
			wave = append(wave, unit.ID)
			continue
		}
		remaining = append(remaining, unit)
	}
	return wave, remaining
}

func declaration(format, formatMin, formatMax, replication, replicationMin, replicationMax uint64) CompatibilityDeclaration {
	return CompatibilityDeclaration{Schema: CompatibilitySchema,
		PersistentFormat: VersionedCapability{Version: format, Accepts: VersionRange{Min: formatMin, Max: formatMax}},
		Replication:      VersionedCapability{Version: replication, Accepts: VersionRange{Min: replicationMin, Max: replicationMax}},
		ClientData:       VersionedCapability{Version: 1, Accepts: VersionRange{Min: 1, Max: 1}}}
}

func (r VersionRange) valid() bool { return r.Min != 0 && r.Min <= r.Max }

// Contains reports whether version lies inside the range.
func (r VersionRange) Contains(version uint64) bool {
	return r.valid() && version >= r.Min && version <= r.Max
}

// VersionedCapability is one versioned interface a release speaks and the
// range of peer versions it was tested to accept.
type VersionedCapability struct {
	Version uint64       `json:"version"`
	Accepts VersionRange `json:"accepts"`
}

func (c VersionedCapability) valid() bool { return c.Version != 0 && c.Accepts.Contains(c.Version) }

// CompatibilityDeclaration is what one release states about its own
// persistent format, replication protocol and client data contract.
type CompatibilityDeclaration struct {
	Schema string `json:"schema"`
	// PersistentFormat.Version is the format the release writes; Accepts is
	// every format it can open.
	PersistentFormat VersionedCapability `json:"persistent_format"`
	// Replication.Version is the replication protocol the release speaks;
	// Accepts is every peer protocol it interoperates with.
	Replication VersionedCapability `json:"replication"`
	// ClientData.Version is the client-visible data contract; Accepts is every
	// contract whose stored client data the release serves unchanged.
	ClientData VersionedCapability `json:"client_data"`
}

// Validate checks the closed structure of a declaration.
func (d CompatibilityDeclaration) Validate() error {
	if d.Schema != CompatibilitySchema {
		return fmt.Errorf("compatibility declaration schema %q is not %s", d.Schema, CompatibilitySchema)
	}
	if !d.PersistentFormat.valid() || !d.Replication.valid() || !d.ClientData.valid() {
		return errors.New("compatibility declaration needs nonzero versions inside their accepted ranges")
	}
	return nil
}

// CompatibilityVerdict is the evidence a compatibility signer may certify for
// replacing a seat running old with candidate, including rolling back.
type CompatibilityVerdict struct {
	// MixedVersionReplication: each release accepts the other's protocol, so
	// the pair keeps replicating while its seats run different releases.
	MixedVersionReplication bool
	// ClientData: each release serves the other's client data contract.
	ClientData bool
	// PersistentFormatRead: the candidate opens what old wrote.
	PersistentFormatRead bool
	// PersistentFormatWrite: old opens what the candidate writes, so a
	// rollback to old can read the volume after the candidate ran.
	PersistentFormatWrite bool
}

// Compatible reports whether every statement holds.
func (v CompatibilityVerdict) Compatible() bool {
	return v.MixedVersionReplication && v.ClientData && v.PersistentFormatRead && v.PersistentFormatWrite
}

// Failures names each statement that does not hold.
func (v CompatibilityVerdict) Failures() []string {
	var failures []string
	if !v.MixedVersionReplication {
		failures = append(failures, "mixed-version replication")
	}
	if !v.ClientData {
		failures = append(failures, "client data")
	}
	if !v.PersistentFormatRead {
		failures = append(failures, "candidate reads predecessor format")
	}
	if !v.PersistentFormatWrite {
		failures = append(failures, "predecessor reads candidate format")
	}
	return failures
}

// Assess derives the compatibility evidence for replacing old with candidate
// from both releases' declarations. It never assumes a statement.
func Assess(old, candidate CompatibilityDeclaration) (CompatibilityVerdict, error) {
	if err := old.Validate(); err != nil {
		return CompatibilityVerdict{}, fmt.Errorf("predecessor %w", err)
	}
	if err := candidate.Validate(); err != nil {
		return CompatibilityVerdict{}, fmt.Errorf("candidate %w", err)
	}
	mutual := func(left, right VersionedCapability) bool {
		return left.Accepts.Contains(right.Version) && right.Accepts.Contains(left.Version)
	}
	return CompatibilityVerdict{
		MixedVersionReplication: mutual(old.Replication, candidate.Replication),
		ClientData:              mutual(old.ClientData, candidate.ClientData),
		PersistentFormatRead:    candidate.PersistentFormat.Accepts.Contains(old.PersistentFormat.Version),
		PersistentFormatWrite:   old.PersistentFormat.Accepts.Contains(candidate.PersistentFormat.Version),
	}, nil
}

// RequireCompatible returns a terminal error unless every statement holds.
func RequireCompatible(old, candidate CompatibilityDeclaration) (CompatibilityVerdict, error) {
	verdict, err := Assess(old, candidate)
	if err != nil {
		return verdict, Terminal(err)
	}
	if !verdict.Compatible() {
		return verdict, Terminal(fmt.Errorf("releases are not compatible: %s", strings.Join(verdict.Failures(), ", ")))
	}
	return verdict, nil
}

type classified struct {
	err   error
	class Class
}

func (c classified) Error() string { return c.err.Error() }
func (c classified) Unwrap() error { return c.err }

// Transient marks err as safe to retry with the same candidate: transport
// failures, a controller leader change, a peer that is briefly not serving,
// or an outcome wait that ended while the seat was still prepared.
func Transient(err error) error {
	if err == nil {
		return nil
	}
	return classified{err: err, class: ClassTransient}
}

// Terminal marks err as requiring human review: a held candidate or
// rollback, an admission rejection, a digest mismatch, a known-bad or
// incompatible candidate.
func Terminal(err error) error {
	if err == nil {
		return nil
	}
	return classified{err: err, class: ClassTerminal}
}

// Classify returns the outermost explicit class of err. Unclassified errors
// are terminal so that automation fails closed.
func Classify(err error) Class {
	var marked classified
	if errors.As(err, &marked) {
		return marked.class
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return ClassTransient
	}
	return ClassTerminal
}

// IsTransient reports whether err may be retried.
func IsTransient(err error) bool { return err != nil && Classify(err) == ClassTransient }

// Backoff is a bounded exponential retry schedule.
type Backoff struct {
	Initial  time.Duration
	Max      time.Duration
	Attempts int
}

// Delay returns the wait before retry attempt (1-based) and whether that
// attempt is still allowed.
func (b Backoff) Delay(attempt int) (time.Duration, bool) {
	if attempt < 1 || attempt > b.Attempts || b.Initial <= 0 {
		return 0, false
	}
	delay := b.Initial
	for range attempt - 1 {
		// Without a cap the doubling would overflow into a negative delay;
		// saturate instead so a long schedule never collapses to no wait.
		if delay > math.MaxInt64/2 {
			delay = math.MaxInt64
		} else {
			delay *= 2
		}
		if b.Max > 0 && delay >= b.Max {
			return b.Max, true
		}
	}
	if b.Max > 0 && delay > b.Max {
		delay = b.Max
	}
	return delay, true
}

// Validate checks the record's identity fields.
func (k KnownBad) Validate() error {
	if !digestRE.MatchString(k.Digest) || k.SeatID == "" || k.Reason == "" || k.RecordedAt.IsZero() {
		return errors.New("known-bad record is incomplete")
	}
	return nil
}

// KnownBadSet answers membership for one deployment.
type KnownBadSet map[string]KnownBad

// Refuse returns a terminal error when digest is known bad.
func (set KnownBadSet) Refuse(digest string) error {
	if record, bad := set[digest]; bad {
		return Terminal(fmt.Errorf("%w: %s failed on seat %s (%s)", ErrKnownBad, digest, record.SeatID, record.Reason))
	}
	return nil
}

// SoakSample is one observation of the seat that already runs the candidate.
type SoakSample struct {
	At             time.Time
	ArtifactDigest string
	OperationID    string
	Phase          string
	// Serving holds when the controller keeps the seat serving and, unless
	// the sample is a Gap, the host's current report proves it serves.
	Serving bool
	// ProcessPID is zero when the controller reports no live host process.
	ProcessPID int
	// Gap marks a sample without a current host report: the controller
	// fields are checked, but the process and its serving proof are unknown.
	Gap bool
}

// ErrSoakFailed marks a candidate that regressed after its serving proof.
var ErrSoakFailed = errors.New("candidate failed its soak")

// Soak gates the next seat on one promoted seat staying healthy for the
// whole window: same candidate and operation, still serving, and the same
// process as when the soak began. A failed soak is terminal; the caller
// treats the candidate as known bad. A gap in host reports is not a failure,
// but the window only completes on a reported sample, and a gap longer than
// the window (at least a minute) ends the soak with a transient error.
type Soak struct {
	Window   time.Duration
	Digest   string
	Promoted string // the update phase that proves the canary served
	first    *SoakSample
	last     time.Time
	// lastPID is the last nonzero process ID; zero means none seen yet.
	lastPID int
	// reported is when the last sample with a host report was taken, or
	// when the soak's gap began if none has been.
	reported time.Time
}

// Observe records one sample. It returns done once the window has elapsed
// with every sample healthy, or a terminal ErrSoakFailed error.
func (s *Soak) Observe(sample SoakSample) (bool, error) {
	if sample.ArtifactDigest != s.Digest || sample.Phase != s.Promoted || !sample.Serving {
		return false, Terminal(fmt.Errorf("%w: seat left %s serving (artifact %s, phase %s, serving %t)",
			ErrSoakFailed, s.Digest, sample.ArtifactDigest, sample.Phase, sample.Serving))
	}
	if s.first != nil && sample.OperationID != s.first.OperationID {
		return false, Terminal(fmt.Errorf("%w: seat operation changed from %s to %s",
			ErrSoakFailed, s.first.OperationID, sample.OperationID))
	}
	if !s.last.IsZero() && sample.At.Before(s.last) {
		return false, errors.New("soak samples went back in time")
	}
	s.last = sample.At
	// Zero is "no live process reported", not a process: such a sample is
	// unknown like a report gap. It neither sets nor breaks the pinned
	// identity, cannot start the window and cannot complete it, so a soak
	// is only ever passed by the process that started it.
	if sample.Gap || sample.ProcessPID == 0 {
		if s.Window <= 0 {
			// A disabled soak checks only the controller's own fields.
			return true, nil
		}
		if s.reported.IsZero() {
			s.reported = sample.At
		}
		if gap := sample.At.Sub(s.reported); gap > max(s.Window, minSoakGap) {
			return false, Transient(fmt.Errorf("seat has had no current host report for %s during its soak", gap))
		}
		return false, nil
	}
	s.reported = sample.At
	if s.lastPID != 0 && sample.ProcessPID != s.lastPID {
		return false, Terminal(fmt.Errorf("%w: seat process restarted (pid %d -> %d)",
			ErrSoakFailed, s.lastPID, sample.ProcessPID))
	}
	s.lastPID = sample.ProcessPID
	if s.first == nil {
		first := sample
		s.first = &first
		return s.Window <= 0, nil
	}
	return !sample.At.Before(s.first.At.Add(s.Window)), nil
}

// Remaining is how long the soak still needs after its first sample.
func (s *Soak) Remaining(now time.Time) time.Duration {
	if s.first == nil {
		return s.Window
	}
	return max(0, s.first.At.Add(s.Window).Sub(now))
}

